        let canvasElem = document.querySelector("canvas");
        canvasElem.addEventListener('mousedown', function(e) {
            meter_nodos_fisicos(canvasElem, e)
        });
        
    }
        
}

nodos_x=[];
nodos_y=[];
function meter_nodos_fisicos(canvas, event) {
    
    var ctx = canvas.getContext("2d");
    const rect = canvas.getBoundingClientRect()
    const x = event.clientX - rect.left
    const y = event.clientY - rect.top
    
    nodos_x.push(x);
    nodos_y.push(y);
    
    
    for(i=0;i<nodos_x.length;i++){
        ctx.fillStyle = "#718E06";
        ctx.fillRect(nodos_x[i],nodos_y[i],10,10); 
    }
   
}

function guardar_nodos(){
    
    camara1=document.getElementById("camara1").value;
    camara2=document.getElementById("camara2").value;
    
    for(i=0;i<nodos_x.length;i++){
        ajax = nuevoAjax();
        urlllamada="pages/config/acciones_ajax.php?a=2&numero_nodos="+nodos_x.length+"&camara1="+camara1+"&camara2="+camara2+"&actual="+i+"&x="+nodos_x[i]+"&y="+nodos_y[i];
        ajax.open("GET", urlllamada, true);

        if(i==(nodos_x.length-1)){
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    location.href="?page=config";
                }
            }
        }
        
        ajax.send(null);
        
    }
}
