var punto=1;             
var lineas_nuevas=0;
function dibuja_linea(canvas, event) {
    //alert("punto:"+punto);
    var ctx = canvas.getContext("2d");
    const rect = canvas.getBoundingClientRect()
    const x = event.clientX - rect.left
    const y = event.clientY - rect.top
    
    ctx.fillStyle = listado_colores[voypocolores];
    ctx.fillRect(x,y,10,10); 
    
    //alert("paso0");
    
    if(punto==2){
        //alert("paso01");
        
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x_lineas[x_lineas.length-1],y_lineas[y_lineas.length-1]);
        ctx.stroke();
        
        //alert("paso02");
        
        txt='<input type="text" name="nombre_linea_nueva_'+lineas_nuevas+'" id="nombre_linea_nueva_'+lineas_nuevas+'" value="" style="border-width:1px;border-style:solid;border-color:'+listado_colores[voypocolores]+'"><br />';
        
        //alert("paso03");
        
        nombres_lineas_capa.innerHTML=nombres_lineas_capa.innerHTML+txt;
        voypocolores++;
        lineas_nuevas++;
                     
        //alert("paso04");
     
    }
    
    
    //alert("paso1:"+x);
    //alert("paso12:"+y);
    x_lineas.push(x);
    y_lineas.push(y);


    //alert("paso2:"+punto);
    
    switch(punto){
        case 1:
            punto=2;
            //alert("modificado a 2");
            break;
        case 2:
            punto=1;
            //alert("modificado a 1");
            break;    
    }
    //alert("paso3");
}


function guardar_lineas(){

    

   
   lasx="";
   lasy="";
   losnombres=""; 
   losids=""; 
   
    
   for(i=0;i<id_lineas.length;i++){
       lasx+=x_lineas[i*2];
       lasx+=",,,";
       lasx+=x_lineas[(i*2)+1];
       
       lasy+=y_lineas[i*2];
       lasy+=",,,";
       lasy+=y_lineas[(i*2)+1];
       
      
       losids+=id_lineas[i];
       losnombres+=document.getElementById("nombre_linea_"+id_lineas[i]).value;
       if(i!=id_lineas.length-1){
           lasx+=",,,";
           lasy+=",,,";
           losids+=",,,";
           losnombres+=",,,";
       }
       

   }
   

   for(j=0;j<lineas_nuevas;j++){
       
       if(lasx!=""){
           lasx+=",,,";
           lasy+=",,,";
           losids+=",,,";
           losnombres+=",,,";
       }
       lasx+=x_lineas[i*2];
       lasx+=",,,";
       lasx+=x_lineas[(i*2)+1];
       
       lasy+=y_lineas[i*2];
       lasy+=",,,";
       lasy+=y_lineas[(i*2)+1];
       
       losids+="0";
       losnombres+=document.getElementById("nombre_linea_nueva_"+j).value;
       

       i++;

   }
   
   url="?page=config&accion=guardar_lineas&lasx="+lasx+"&lasy="+lasy+"&losnombres="+losnombres+"&losids="+losids+"&camara_id="+document.getElementById("camara1_linea").value+"&mostrar_foto="+document.getElementById("camara1_linea").value;
   
   location.href=url; 
    
 
}

